      ["in Oslo =",["på Oslo","i Oslo","til Oslo","av Oslo"],1,"The chunk is i Oslo. til Oslo means to Oslo."],
      ["straight ahead =",["til høyre","til venstre","på fram","rett fram"],3,"rett fram means straight ahead."]
